  // agenda por semana: cfg.agendas guarda agendas que começam numa segunda-feira; cada semana usa a última que começou
  // até ela (semanas anteriores à primeira usam cfg.semana, a agenda inicial). Mudar uma semana não mexe nas anteriores
  const agendaKey = (dateISO, cfg) => { const mk = iso(monday(parseISO(dateISO))); return Object.keys(cfg.agendas || {}).filter(k => k <= mk).sort().pop() || null; };
  const agendaFor = (dateISO, cfg) => { const k = agendaKey(dateISO, cfg); return (k ? cfg.agendas[k] : cfg.semana) || {}; };
  const planFor = (dateISO, cfg) => agendaFor(dateISO, cfg)[DOW[dowIdx(dateISO)]] || { forca: false, cardioMin: 0, cardioTipo: "Esteira inclinada leve (5 km/h)" };
