    const term = (l, v, c) => `<div class="be-t" style="--c:${c}"><small>${l}</small><b>${v == null ? "—" : n0(v)}</b></div>`, op = s => `<span class="be-op">${s}</span>`;
    $("w-bal").innerHTML = `
      <div class="bal-main">
        ${term("Consumo", tot("ing"), "var(--m-kcal)")}${op("−")}${op("(")}${term("Base", tot("base"), "var(--ink)")}${op("+")}${term("Treino", tot("f"), "var(--musc)")}${op("+")}${term("Cardio", tot("c"), "var(--n-purple)")}${op(")")}${op("=")}
        <div class="bal-res ${toneOf(wSal)}"><small>Balanço da semana</small><b>${wSal == null ? "—" : sgn(wSal)}<span> kcal</span></b><em>${wSal == null ? "sem alimentação registrada" : `${B.length}/7 dias registrados · ${wSal < 0 ? "déficit" : "superávit"}`}</em></div>
        <div class="bal-res bal-avg ${toneOf(wAvgB)}"><small>Média por dia</small><b>${wAvgB == null ? "—" : sgn(wAvgB)}<span> kcal</span></b><em>${goal}${wAvgB != null && pAvgB != null ? ` · sem. ant. ${sgn(pAvgB)}` : ""}</em></div>
      </div>`;
    // indicadores: média diária de cada macro (dias registrados) contra a média da meta nesses dias; depois treino, cardio e peso
    const L = days.filter(d => S.days[d]), el = days.filter(d => d <= todayISO), base = L.length ? L : el.length ? el : days;
    const avgOf = (arr, f) => arr.length ? sum(arr.map(f)) / arr.length : 0;
    const mv = k => avgOf(L, d => S.days[d][k] || 0), mt = k => avgOf(base, d => dayTarget(d)[k] || 0), noFood = !L.length;
    const kc = { val: mv("kcal"), tgt: mt("kcal") }, kgW = W.wAvg || weightOn(days[6])?.kg;
