    const cKm = sum(days.flatMap(d => sessOn(d).map(s => s.cardio?.km || 0)));
    const fMin = sum(days.flatMap(d => sessOn(d).filter(s => s.forca).map(s => s.duracaoMin || 0)));
    $("w-kpis").innerHTML = macroCard("kcal", "Calorias · média", "var(--m-kcal)", kc.val, kc.tgt, "kcal", noFood)
