      + macroCard("C", "Carbo · média", "var(--m-carb)", mv("carb"), mt("carb"), "g", noFood, kc)
      + macroCard("F", "Gordura · média", "var(--m-gord)", mv("gord"), mt("gord"), "g", noFood, kc) + `
      <div class="kpi kpi-tile" style="--c:var(--musc)"><div class="mr-body"><span class="label">Treinos</span><span class="value kv-frac">${W.fDone}${sm(` / ${W.fPlan}${cur ? " até hoje" : ""}`)}</span><span class="sub">${W.sets} séries ${dlt(W.sets, P.sets, v => n0(v))} · ${n0(W.vol)} kg${fMin ? ` · ${n0(fMin)} min` : ""}</span></div><div class="kt-vis"><i class="ic" data-i="dumbbell"></i></div></div>
      <div class="kpi kpi-tile" style="--c:var(--n-purple)"><div class="mr-body"><span class="label">Cardio</span><span class="value kv-frac">${n0(W.cDone)}${sm(` / ${n0(W.cPlan)} min`)}</span><span class="sub">${[cKm ? `${n1(cKm)} km` : "", cK ? `≈ ${n0(cK)} kcal` : ""].filter(Boolean).join(" · ") || "nenhum cardio registrado"} ${dlt(W.cDone, P.cDone, v => n0(v) + " min")}</span></div><div class="kt-vis"><i class="ic" data-i="activity"></i></div></div>
      <div class="kpi kpi-tile" style="--c:var(--ink-2)"><div class="mr-body"><span class="label">Peso · média</span><span class="value">${W.wAvg != null ? `${n1(W.wAvg)}${sm(" kg")}` : "—"}</span><span class="sub">${wd != null ? `${fmtKg(wd)} vs semana anterior` : W.wAvg != null ? "sem pesagem na semana anterior" : "sem pesagens nesta semana"}${rate ? ` · plano ${fmtKg(rate)}/sem` : ""}</span></div><div class="kt-vis"><i class="ic" data-i="scale"></i></div></div>`;
