    $("t-ex").innerHTML = GROUPS.map(g => { const ex = names.filter(nm => H[nm].grupo === g).sort(); return ex.length ? `<optgroup label="${g}">${ex.map(nm => `<option value="${esc(nm)}"${nm === S.ex ? " selected" : ""}>${esc(nm)} (${H[nm].pts.length})</option>`).join("")}</optgroup>` : ""; }).join("");
    renderProg(H); renderLifts(H); renderVolHeat(H); renderCardio(); renderFoods();
