    const txtCol = v => v >= 10 ? "#fff" : "var(--ink)";
    $("g-vol").innerHTML = `<table><thead><tr><th></th>${weeks.map((w, i) => `<th class="${i === 11 ? "cur" : ""}">${i % 2 === 1 || i === 11 ? ddmm(iso(w)) : ""}</th>`).join("")}<th>média</th></tr></thead><tbody>${GROUPS.map(g => {
      const a = vol[g], avg = sum(a.slice(0, 11)) / 11;
      return `<tr><td class="g" data-g="${g}">${g}</td>${a.map((v, i) => `<td class="${i === 11 ? "cur" : ""}" style="background:${v ? bmFill(v) : "var(--surface-2)"};color:${txtCol(v)}" title="${g} · semana de ${ddmm(iso(weeks[i]))}: ${v} séries${i === 11 ? " (semana atual)" : ""}">${v || ""}</td>`).join("")}<td style="font-weight:600">${n1(avg)}</td></tr>`;
    }).join("")}</tbody></table><p class="hint" style="margin-top:6px">Mesmas faixas do mapa: vazio = nenhuma série, verde = 10–20, laranja = acima de 20. A média ignora a semana atual, que ainda não terminou.</p>`;
